using NaturalSort.Extension;
using System;
using System.Collections.Generic;
using System.Linq;

namespace MECCG_Deck_Builder
{
    public sealed class Deck
    {
        public string Title { get; set; } = "New Deck";
        public HashSet<string> IncludedSets { get; } = new(StringComparer.OrdinalIgnoreCase);

        public List<Card> Pool { get; } = [];
        public List<Card> Resources { get; } = [];
        public List<Card> Hazards { get; } = [];
        public List<Card> Sideboard { get; } = [];
        public List<Card> Sites { get; } = [];

        public List<Card> GetSection(DeckSectionType sectionType) => sectionType switch
        {
            DeckSectionType.Pool => Pool,
            DeckSectionType.Resources => Resources,
            DeckSectionType.Hazards => Hazards,
            DeckSectionType.Sideboard => Sideboard,
            DeckSectionType.Sites => Sites,
            _ => throw new ArgumentOutOfRangeException(nameof(sectionType))
        };

        public int CountCharactersInResources()
        {
            return Resources.Count(c => string.Equals(c.Primary, "Character", StringComparison.OrdinalIgnoreCase));
        }

        public void Clear()
        {
            Title = "New Deck";
            IncludedSets.Clear();
            Pool.Clear();
            Resources.Clear();
            Hazards.Clear();
            Sideboard.Clear();
            Sites.Clear();
        }

        public void SortSections()
        {
            static int CompareCards(Card a, Card b) => StringComparer.CurrentCultureIgnoreCase.WithNaturalSort().Compare(a.Name, b.Name);

            Pool.Sort(CompareCards);
            Resources.Sort(CompareCards);
            Hazards.Sort(CompareCards);
            Sideboard.Sort(CompareCards);
            Sites.Sort(CompareCards);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace MECCG_Deck_Builder
{
    public static class DeckExportService
    {
        public static void ExportToText(Deck deck, string filePath)
        {
            var sb = new StringBuilder();

            foreach (DeckSectionType sectionType in Enum.GetValues<DeckSectionType>())
            {
                sb.AppendLine(sectionType.ToString());
                sb.AppendLine();
                foreach (var card in deck.GetSection(sectionType))
                {
                    sb.AppendLine(card.Name);
                }
                sb.AppendLine();
            }

            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        public static void ExportToPlayMeccg(Deck deck, string filePath)
        {
            var sb = new StringBuilder();
            var ansiEncoding = Encoding.GetEncoding(1252);

            // Pool
            sb.AppendLine("####");
            sb.AppendLine("Pool");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Pool)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            // Deck (Resources + Hazards combined)
            sb.AppendLine("####");
            sb.AppendLine("Deck");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Resources)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            foreach (var card in deck.Hazards)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            // Sideboard
            sb.AppendLine("####");
            sb.AppendLine("Sideboard");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Sideboard)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            // Sites
            sb.AppendLine("####");
            sb.AppendLine("Sites");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Sites)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            File.WriteAllText(filePath, sb.ToString(), ansiEncoding);
        }

        public static void ExportToCardnum(Deck deck, string filePath)
        {
            var sb = new StringBuilder();

            foreach (DeckSectionType sectionType in Enum.GetValues<DeckSectionType>())
            {
                sb.AppendLine(sectionType.ToString());
                sb.AppendLine();
                foreach (var card in deck.GetSection(sectionType))
                {
                    if (!string.IsNullOrEmpty(card.FullCode))
                    {
                        sb.AppendLine($"1 {card.FullCode}");
                    }
                }
                sb.AppendLine();
            }

            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        public static void ExportToArchive(Deck deck, string filePath)
        {
            string[] archiveCategories =
            [
                "Minor Item", "Major Item", "Greater Item", "Gold Ring Item", "Special Item",
                "Resource Short", "Resource Long", "Resource Permanent", "Ally", "Faction",
                "Creature Unique", "Creature", "Hazard Short", "Hazard Long", "Hazard Permanent",
                "Dunadan", "Dwarf", "Elf", "Hobbit", "Man (Wose)", "Wizard",
                "Free-hold", "Border-hold", "Ruins & Lairs", "Shadow-hold", "Dark-hold", "Region"
            ];

            int totalArchived = 0;
            var cardDataByCategory = new Dictionary<string, Dictionary<string, List<string>>>(StringComparer.OrdinalIgnoreCase);

            foreach (string cat in archiveCategories)
            {
                cardDataByCategory[cat] = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            }

            foreach (DeckSectionType sectionType in Enum.GetValues<DeckSectionType>())
            {
                foreach (var card in deck.GetSection(sectionType))
                {
                    string primary = card.Primary;
                    string secondary = TruncateSlash(card.Secondary);
                    string unique = card.Unique;
                    string race = card.Race;
                    string site = card.Site;

                    string categoryKey = GetArchiveCategoryKey(primary, secondary, unique, race, site);
                    if (string.IsNullOrEmpty(categoryKey) || !cardDataByCategory.TryGetValue(categoryKey, out var setsInCategory))
                    {
                        continue;
                    }

                    string setKey = card.Set;
                    if (!setsInCategory.TryGetValue(setKey, out var cardsInSet))
                    {
                        cardsInSet = [];
                        setsInCategory[setKey] = cardsInSet;
                    }

                    cardsInSet.Add(card.Name);
                    totalArchived++;
                }
            }

            using var writer = new StreamWriter(filePath, false, Encoding.UTF8);
            writer.WriteLine($"--- {filePath} ({totalArchived} cards) ---");
            writer.WriteLine();

            foreach (var categoryEntry in cardDataByCategory)
            {
                string categoryTitle = categoryEntry.Key;
                var setsInThisCategory = categoryEntry.Value;

                writer.WriteLine($"--- CATEGORY: {categoryTitle} ---");

                foreach (var setEntry in setsInThisCategory)
                {
                    string setTitle = setEntry.Key;
                    var cardsInThisSet = setEntry.Value;

                    if (cardsInThisSet.Count == 0)
                    {
                        continue;
                    }

                    writer.WriteLine($"\tSET: {setTitle} ({cardsInThisSet.Count})");
                    foreach (string cardName in cardsInThisSet)
                    {
                        writer.WriteLine($"\t\t{cardName}");
                    }
                }
                writer.WriteLine();
            }
        }

        public static void ExportToTts(IReadOnlyList<Card> cards, string filePath)
        {
            var sb = new StringBuilder();
            sb.Append("{\n\t\"ObjectStates\": [\n\t\t{\n\t\t\t\"Name\": \"Deck\",\n");
            sb.Append(GetTtsTransform(3));
            sb.Append("\t\t\t\"DeckIDs\": [\n");

            for (int i = 0; i < cards.Count; i++)
            {
                sb.Append($"\t\t\t\t{(i + 1) * 100}");
                if (i != cards.Count - 1) sb.Append(',');
                sb.Append('\n');
            }
            sb.Append("\t\t\t],\n\t\t\t\"CustomDeck\": {\n");

            for (int i = 0; i < cards.Count; i++)
            {
                sb.Append(GetTtsCustomDeck(cards[i], i + 1, 4));
                if (i != cards.Count - 1) sb.Append(',');
                sb.Append('\n');
            }
            sb.Append("\t\t\t},\n\t\t\t\"ContainedObjects\": [\n");

            for (int i = 0; i < cards.Count; i++)
            {
                string escapedName = cards[i].Name.Replace("\"", "\\\"");
                sb.Append("\t\t\t\t{\n\t\t\t\t\t\"Name\": \"Card\",\n");
                sb.Append(GetTtsTransform(5));
                sb.Append("\t\t\t\t\t\"CustomDeck\": {\n");
                sb.Append(GetTtsCustomDeck(cards[i], i + 1, 6));
                sb.Append("\n\t\t\t\t\t},\n");
                sb.Append($"\t\t\t\t\t\"Nickname\": \"{escapedName}\",\n");
                sb.Append($"\t\t\t\t\t\"CardID\": \"{(i + 1) * 100}\"\n");
                sb.Append("\t\t\t\t}");
                if (i != cards.Count - 1) sb.Append(',');
                sb.Append('\n');
            }

            sb.Append("\t\t\t]\n\t\t}\n\t]\n}\n");
            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        #region HELPERS

        private static string FormatPlayMeccgCardName(string cardName)
        {
            if (cardName.Contains(" - "))
            {
                string cleanName = cardName.Replace("\"", "");
                int dashIndex = cleanName.IndexOf(" - ", StringComparison.Ordinal);
                string mainTitle = cleanName[..dashIndex].Trim();
                string subTitle = cleanName[(dashIndex + 3)..].Trim();
                return $"{mainTitle} ({subTitle})";
            }
            return cardName;
        }

        private static string TruncateSlash(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            int slashIndex = value.IndexOf('/');
            return slashIndex >= 0 ? value[..slashIndex].Trim() : value.Trim();
        }

        private static string GetArchiveCategoryKey(string primary, string secondary, string unique, string race, string site)
        {
            if (primary.Equals("Resource", StringComparison.OrdinalIgnoreCase))
            {
                return secondary switch
                {
                    "Minor Item" => "Minor Item",
                    "Major Item" => "Major Item",
                    "Greater Item" => "Greater Item",
                    "Gold Ring Item" => "Gold Ring Item",
                    "Special Item" => "Special Item",
                    "Short-event" => "Resource Short",
                    "Long-event" => "Resource Long",
                    "Permanent-event" => "Resource Permanent",
                    "Ally" => "Ally",
                    "Faction" => "Faction",
                    _ => string.Empty
                };
            }

            if (secondary.Equals("Creature", StringComparison.OrdinalIgnoreCase))
            {
                return unique.Equals("unique", StringComparison.OrdinalIgnoreCase) ? "Creature Unique" : "Creature";
            }

            if (primary.Equals("Hazard", StringComparison.OrdinalIgnoreCase))
            {
                return secondary switch
                {
                    "Short-event" => "Hazard Short",
                    "Long-event" => "Hazard Long",
                    "Permanent-event" => "Hazard Permanent",
                    _ => string.Empty
                };
            }

            if (primary.Equals("Character", StringComparison.OrdinalIgnoreCase))
            {
                if (race.Equals("Dúnadan", StringComparison.OrdinalIgnoreCase)) return "Dunadan";
                return race switch
                {
                    "Dwarf" => "Dwarf",
                    "Elf" => "Elf",
                    "Hobbit" => "Hobbit",
                    "Man" => "Man (Wose)",
                    "Wizard" => "Wizard",
                    _ => string.Empty
                };
            }

            if (primary.Equals("Site", StringComparison.OrdinalIgnoreCase))
            {
                return site switch
                {
                    "Free-hold" => "Free-hold",
                    "Border-hold" => "Border-hold",
                    "Ruins & Lairs" => "Ruins & Lairs",
                    "Shadow-hold" => "Shadow-hold",
                    "Dark-hold" => "Dark-hold",
                    "Region" => "Region",
                    _ => string.Empty
                };
            }

            if (primary.Equals("Region", StringComparison.OrdinalIgnoreCase))
            {
                return "Region";
            }

            return string.Empty;
        }

        private static string GetTtsTransform(int tabCount)
        {
            string tabs = new('\t', tabCount);
            return $"{tabs}\"Transform\": {{\n{tabs}\t\"RotY\": 180.0,\n{tabs}\t\"RotZ\": 180.0,\n{tabs}\t\"ScaleX\": 1.0,\n{tabs}\t\"ScaleY\": 1.0,\n{tabs}\t\"ScaleZ\": 1.0\n{tabs}}},\n";
        }

        private static string GetTtsCustomDeck(Card card, int index, int tabCount)
        {
            string tabs = new('\t', tabCount);
            return $"{tabs}\"{index}\": {{\n" +
                   $"{tabs}\t\"FaceURL\": \"https://cardnum.net/img/cards/{card.Set}/{card.ImageName}\",\n" +
                   $"{tabs}\t\"BackURL\": \"https://i.imgur.com/gUPyTI4.jpg\",\n" +
                   $"{tabs}\t\"BackIsHidden\": \"true\",\n" +
                   $"{tabs}\t\"NumWidth\": 1,\n" +
                   $"{tabs}\t\"NumHeight\": 1\n" +
                   $"{tabs}}}";
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;

namespace MECCG_Deck_Builder
{
    public sealed class DeckGenerationRuleSet
    {
        public string DeckTitle { get; set; } = "Generated Deck";
        public string RuleSetType { get; set; } = "SequentialRules";
        public string Version { get; set; } = "1.0";
        public List<DeckGenerationRule> Rules { get; set; } = [];
    }

    public sealed class DeckGenerationChoice
    {
        public string Name { get; set; } = string.Empty;
        public string DeckTitle { get; set; } = string.Empty;
        public int Weight { get; set; } = 1;
        public List<DeckGenerationRule> Rules { get; set; } = [];
    }

    public sealed class DeckGenerationRule
    {
        public string RuleType { get; set; } = "FilterQuery";
        public string Name { get; set; } = string.Empty;
        public string SaveAs { get; set; } = string.Empty; // <-- ADD THIS
        public string Section { get; set; } = "Resources";
        public int Count { get; set; } = 1;
        public List<string> Sets { get; set; } = [];
        public Dictionary<string, string> Attributes { get; set; } = new(StringComparer.OrdinalIgnoreCase);
        public Dictionary<string, string> Tags { get; set; } = new(StringComparer.OrdinalIgnoreCase);
        public DeckGenerationRule Fallback { get; set; }
        public List<DeckGenerationChoice> Choices { get; set; } = [];
    }

    public sealed class DeckRuleExecutionLog
    {
        public string RuleName { get; init; } = string.Empty;
        public string Section { get; init; } = string.Empty;
        public int RequestedCount { get; init; }
        public int AddedCount { get; init; }
        public bool IsShortfall => AddedCount < RequestedCount;
    }

    public sealed class DeckGenerationResult
    {
        public Deck Deck { get; init; } = new();
        public List<DeckRuleExecutionLog> Logs { get; init; } = [];
        public bool Success { get; init; }
        public string ErrorMessage { get; init; } = string.Empty;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Newtonsoft.Json;

namespace MECCG_Deck_Builder
{
    public static class DeckGenerationService
    {
#pragma warning disable SYSLIB1045 // Use 'GeneratedRegexAttribute'
        private static readonly Regex PlaceholderRegex = new(
            @"\{([a-zA-Z0-9_]+)\.(?:Tag:([^}]+)|([a-zA-Z0-9_]+))\}",
            RegexOptions.Compiled | RegexOptions.IgnoreCase);
#pragma warning restore SYSLIB1045

        public static DeckGenerationRuleSet LoadRuleSetFromJson(string json)
        {
            if (string.IsNullOrWhiteSpace(json)) return null;
            return JsonConvert.DeserializeObject<DeckGenerationRuleSet>(json);
        }

        public static string SaveRuleSetToJson(DeckGenerationRuleSet ruleSet)
        {
            return JsonConvert.SerializeObject(ruleSet, Formatting.Indented);
        }

        public static DeckGenerationResult GenerateDeck(
            IEnumerable<Card> catalogCards,
            ISet<string> defaultSets,
            CardFilterService filterService,
            DeckGenerationRuleSet ruleSet)
        {
            if (ruleSet == null || ruleSet.Rules == null || ruleSet.Rules.Count == 0)
            {
                return new DeckGenerationResult
                {
                    Success = false,
                    ErrorMessage = "The rule set contains no rules."
                };
            }

            var deck = new Deck
            {
                Title = !string.IsNullOrWhiteSpace(ruleSet.DeckTitle) ? ruleSet.DeckTitle : "Generated Deck"
            };

            var cardCountsByName = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var contextVariables = new Dictionary<string, List<Card>>(StringComparer.OrdinalIgnoreCase);
            var logs = new List<DeckRuleExecutionLog>();
            var allCards = catalogCards?.ToList() ?? [];

            foreach (var rule in ruleSet.Rules)
            {
                ExecuteRule(rule, deck, cardCountsByName, logs, allCards, defaultSets, filterService, contextVariables);
            }

            deck.SortSections();

            return new DeckGenerationResult
            {
                Deck = deck,
                Logs = logs,
                Success = true
            };
        }

        private static void ExecuteRule(
            DeckGenerationRule rule,
            Deck deck,
            Dictionary<string, int> cardCountsByName,
            List<DeckRuleExecutionLog> logs,
            IReadOnlyList<Card> allCards,
            ISet<string> defaultSets,
            CardFilterService filterService,
            Dictionary<string, List<Card>> contextVariables = null)
        {
            if (rule == null) return;

            contextVariables ??= new Dictionary<string, List<Card>>(StringComparer.OrdinalIgnoreCase);

            // Handle RandomChoice / ChoiceGroup ("OR" branches)
            if (IsChoiceRule(rule))
            {
                var validChoices = rule.Choices?.Where(c => c != null && c.Rules != null && c.Rules.Count > 0).ToList() ?? [];
                if (validChoices.Count == 0) return;

                int totalWeight = validChoices.Sum(c => Math.Max(1, c.Weight));
                int roll = Random.Shared.Next(totalWeight);
                int cumulative = 0;
                DeckGenerationChoice chosen = validChoices[0];

                foreach (var c in validChoices)
                {
                    cumulative += Math.Max(1, c.Weight);
                    if (roll < cumulative)
                    {
                        chosen = c;
                        break;
                    }
                }

                if (!string.IsNullOrWhiteSpace(chosen.DeckTitle))
                {
                    deck.Title = chosen.DeckTitle;
                }

                logs.Add(new DeckRuleExecutionLog
                {
                    RuleName = $"[Branch Selected] {rule.Name} -> '{chosen.Name}'",
                    Section = "-",
                    RequestedCount = 0,
                    AddedCount = 0
                });

                foreach (var subRule in chosen.Rules)
                {
                    ExecuteRule(subRule, deck, cardCountsByName, logs, allCards, defaultSets, filterService, contextVariables);
                }
                return;
            }

            // Standard FilterQuery Rule
            if (rule.Count <= 0) return;

            if (!Enum.TryParse<DeckSectionType>(rule.Section, true, out var sectionType))
            {
                sectionType = DeckSectionType.Resources;
            }

            ISet<string> ruleSets = (rule.Sets != null && rule.Sets.Count > 0)
                ? new HashSet<string>(rule.Sets, StringComparer.OrdinalIgnoreCase)
                : defaultSets;

            // 1. Resolve runtime variable placeholders in Attributes & Tags
            var resolvedAttributes = new Dictionary<string, (string RawTemplate, string ResolvedValue)>(StringComparer.OrdinalIgnoreCase);
            if (rule.Attributes != null)
            {
                foreach (var (attrKey, rawVal) in rule.Attributes)
                {
                    if (string.IsNullOrWhiteSpace(attrKey)) continue;
                    string resolved = ResolvePlaceholders(rawVal, contextVariables, filterService);
                    resolvedAttributes[attrKey] = (rawVal, resolved);
                }
            }

            var resolvedTags = new Dictionary<string, (string RawTemplate, string ResolvedValue)>(StringComparer.OrdinalIgnoreCase);
            if (rule.Tags != null)
            {
                foreach (var (tagKey, rawVal) in rule.Tags)
                {
                    if (string.IsNullOrWhiteSpace(tagKey)) continue;
                    string resolved = ResolvePlaceholders(rawVal, contextVariables, filterService);
                    resolvedTags[tagKey] = (rawVal, resolved);
                }
            }

            // 2. Filter candidates
            var candidates = allCards.Where(c =>
            {
                if (ruleSets != null && ruleSets.Count > 0 && !ruleSets.Contains(c.Set))
                {
                    return false;
                }

                // Attribute evaluation
                foreach (var (attrKey, (rawTemplate, resolvedVal)) in resolvedAttributes)
                {
                    // If placeholder was specified (e.g. {Leader.Tag:Faction Bonus}) but resolved empty,
                    // the dependency was not met: do not match any card.
                    if (!string.IsNullOrWhiteSpace(rawTemplate) && string.IsNullOrWhiteSpace(resolvedVal))
                    {
                        return false;
                    }

                    if (!string.IsNullOrWhiteSpace(resolvedVal))
                    {
                        var allowedValues = resolvedVal.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                        if (!allowedValues.Any(v => CardFilterService.MatchesCardnumCriterion(c, attrKey, v)))
                        {
                            return false;
                        }
                    }
                }

                // Tag evaluation
                if (filterService != null)
                {
                    foreach (var (tagKey, (rawTemplate, resolvedVal)) in resolvedTags)
                    {
                        if (!string.IsNullOrWhiteSpace(rawTemplate) && string.IsNullOrWhiteSpace(resolvedVal))
                        {
                            return false;
                        }

                        if (!string.IsNullOrWhiteSpace(resolvedVal))
                        {
                            var allowedTags = resolvedVal.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                            if (!allowedTags.Any(t => filterService.MatchesCustomCriterion(c.Id, tagKey, t)))
                            {
                                return false;
                            }
                        }
                    }
                }

                return true;
            }).ToList();

            // 3. Sample candidates with tiered variety-first distribution
            int addedForThisRule = 0;
            var targetSection = deck.GetSection(sectionType);
            var newlyAdded = new List<Card>();

            while (addedForThisRule < rule.Count)
            {
                var available = candidates.Where(c => CanAddCard(c, cardCountsByName)).ToList();
                if (available.Count == 0) break;

                int minCount = available.Min(c => cardCountsByName.GetValueOrDefault(c.Name, 0));

                var tierGroups = available
                    .Where(c => cardCountsByName.GetValueOrDefault(c.Name, 0) == minCount)
                    .GroupBy(c => c.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                if (tierGroups.Count == 0) break;

                int groupIndex = Random.Shared.Next(tierGroups.Count);
                var matchingReprints = tierGroups[groupIndex].ToList();
                var selectedCard = matchingReprints[Random.Shared.Next(matchingReprints.Count)];

                targetSection.Add(selectedCard);
                deck.IncludedSets.Add(selectedCard.Set);
                newlyAdded.Add(selectedCard);

                int currentCount = cardCountsByName.GetValueOrDefault(selectedCard.Name, 0) + 1;
                cardCountsByName[selectedCard.Name] = currentCount;
                addedForThisRule++;
            }

            // 4. Capture selected cards to variable context if SaveAs is specified
            if (!string.IsNullOrWhiteSpace(rule.SaveAs) && newlyAdded.Count > 0)
            {
                contextVariables[rule.SaveAs] = newlyAdded;
            }

            // 5. If shortfall occurred and a Fallback rule is defined, execute it for remaining count
            if (addedForThisRule < rule.Count && rule.Fallback != null)
            {
                int remainingNeeded = rule.Count - addedForThisRule;
                rule.Fallback.Count = remainingNeeded;

                if (string.IsNullOrWhiteSpace(rule.Fallback.Section))
                {
                    rule.Fallback.Section = sectionType.ToString();
                }

                int countBefore = targetSection.Count;
                ExecuteRule(rule.Fallback, deck, cardCountsByName, logs, allCards, defaultSets, filterService, contextVariables);
                int addedByFallback = targetSection.Count - countBefore;

                // The fallback's own ExecuteRule already logged its results accurately,
                // so return to avoid duplicate/conflicting log entries.
                return;
            }
        }

        private static string ResolvePlaceholders(
            string template,
            Dictionary<string, List<Card>> contextVariables,
            CardFilterService filterService)
        {
            if (string.IsNullOrWhiteSpace(template) || !template.Contains('{'))
            {
                return template ?? string.Empty;
            }

            return PlaceholderRegex.Replace(template, match =>
            {
                string varName = match.Groups[1].Value;
                if (!contextVariables.TryGetValue(varName, out var cards) || cards.Count == 0)
                {
                    return string.Empty;
                }

                var resolvedValues = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                if (match.Groups[2].Success && !string.IsNullOrWhiteSpace(match.Groups[2].Value))
                {
                    // Custom taxonomy tag lookup: {Variable.Tag:Category Name}
                    string category = match.Groups[2].Value.Trim();
                    if (filterService != null)
                    {
                        foreach (var card in cards)
                        {
                            var tags = filterService.GetCardTagsForCategory(card.Id, category);
                            foreach (var tag in tags)
                            {
                                if (!string.IsNullOrWhiteSpace(tag))
                                {
                                    resolvedValues.Add(tag.Trim());
                                }
                            }
                        }
                    }
                }
                else if (match.Groups[3].Success && !string.IsNullOrWhiteSpace(match.Groups[3].Value))
                {
                    // Official Cardnum attribute lookup: {Variable.AttributeName}
                    string attrName = match.Groups[3].Value.Trim();
                    foreach (var card in cards)
                    {
                        string val = card.GetAttribute(attrName);
                        if (!string.IsNullOrWhiteSpace(val))
                        {
                            // Also split multi-values (e.g., compound skills or dual homes)
                            var parts = val.Split([';', ','], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                            foreach (var part in parts)
                            {
                                resolvedValues.Add(part);
                            }
                        }
                    }
                }

                return resolvedValues.Count > 0 ? string.Join("; ", resolvedValues) : string.Empty;
            }).Trim();
        }

        private static bool IsChoiceRule(DeckGenerationRule rule)
        {
            if (rule == null) return false;
            return string.Equals(rule.RuleType, "RandomChoice", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(rule.RuleType, "Choice", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(rule.RuleType, "OneOf", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(rule.RuleType, "Or", StringComparison.OrdinalIgnoreCase) ||
                   (rule.Choices != null && rule.Choices.Count > 0);
        }

        private static bool CanAddCard(Card card, Dictionary<string, int> cardCountsByName)
        {
            int currentCount = cardCountsByName.GetValueOrDefault(card.Name, 0);
            int maxAllowed = IsUniqueCard(card) ? 1 : 3;
            return currentCount < maxAllowed;
        }

        private static bool IsUniqueCard(Card card)
        {
            return string.Equals(card.Unique, "Unique", StringComparison.OrdinalIgnoreCase);
        }
    }
}

namespace MECCG_Deck_Builder
{
    public enum DeckSectionType
    {
        Pool,
        Resources,
        Hazards,
        Sideboard,
        Sites
    }
}

namespace MECCG_Deck_Builder
{
    public enum FilterType
    {
        Cardnum,
        Custom
    }

    public sealed record FilterCriterion(FilterType Type, string Key, string Value)
    {
        public bool IsActive => !string.IsNullOrWhiteSpace(Key) && !string.IsNullOrWhiteSpace(Value);
    }
}

